// Live help assistant — answer engine (loaded only when the chat is opened).
//
// Knowledge sources (all already published on the site, each answer links back to its page):
//   • hand-written intents ............ src/data/chat/intents.js
//   • FAQ page ........................ src/data/faqs.js (FAQ_GROUPS, HOW_FAQ)
//   • audience pages FAQs ............. src/data/audiences.js (AUDIENCE_FAQ)
//   • every blog post FAQ ............. src/data/chat/blogFaq.js (generated by scripts/chat-kb.mjs)
//   • Privacy / Terms / GDPR / Cookies  src/data/legal.js
//   • quality & verification checks ... src/data/quality.js
// Plus entity look-ups: any of the world's countries (covered or not), 195+ conditions, 1,300+ job titles.
//
// Matching is a small keyword-weighted search (synonyms + light stemming + IDF), so it runs instantly in
// the browser with no external service. If nothing scores high enough, respond() returns
// { unknown: true } and the chat asks for the visitor's details so a person can answer.
import { INTENTS } from '../../data/chat/intents.js';
import { BLOG_FAQ } from '../../data/chat/blogFaq.js';
import { FAQ_GROUPS, HOW_FAQ } from '../../data/faqs.js';
import { AUDIENCE, AUDIENCE_FAQ } from '../../data/audiences.js';
import { LEGAL } from '../../data/legal.js';
import { QUALITY_CHECKS, VERIFICATION_PROTOCOLS } from '../../data/quality.js';
import { ALL_COUNTRIES, COVERAGE, REGIONS } from '../../data/countries.js';
import { THERAPY_AREAS, CONDITION_COUNT } from '../../data/conditions.js';
import { allJobs } from '../../data/hcpProfile.js';
import { RATE_BANDS } from '../../data/surveys.js';

/* ---------------- text helpers ---------------- */
const STOP = new Set('a an the is are am i im me my mine we us our you your yours to of in on for and or do does did can could would should will shall it its this that these those be been being how what whats why when where which who whom with at as from by about please pls plz any there have has had was were if so just also than then there their them they he she his her want need know tell like let some many more most get got give make kindly sir madam maam dear'.split(' '));
const KEEP_SHORT = new Set(['hi', 'yo', 'ok', 'gp', 'it', 'uk', 'us', 'pr', 'id', 'dr', 'hr', 'ot', 'ent', 'ivf', 'ibs', 'hiv', 'upi', 'otp', 'pin', 'vpn', 'tor', 'sms', 'cv', 'no', 'not']);

const SYN = {};
[
  ['pay', 'pay paid pays paying payment payments payout payouts earn earns earned earning earnings money cash reward rewards incentive incentives honorarium honoraria compensation compensate payed amount dollar dollars usd'],
  ['redeem', 'redeem redeemed redemption withdraw withdrawal withdrawals cashout encash claim transfer'],
  ['join', 'join joining joined signup register registered registration enrol enroll enrolment enrollment membership member members'],
  ['survey', 'survey surveys study studies questionnaire questionnaires poll polls research'],
  ['doctor', 'doctor doctors physician physicians dr gp consultant'],
  ['nurse', 'nurse nurses nursing midwife'],
  ['delete', 'delete deleting remove close deactivate erase cancel'],
  ['email', 'email emails mail mails gmail inbox'],
  ['mobile', 'phone mobile cell smartphone android iphone'],
  ['data', 'data information info details personal'],
  ['safe', 'safe safety secure security protect protected protection privacy private confidential'],
  ['free', 'free fee fees cost costs charge charges'],
  ['country', 'country countries nation nations'],
  ['time', 'long duration minute minutes mins hour hours'],
  ['invite', 'invite invites invitation invitations notification notifications alert alerts'],
  ['legit', 'legit legitimate genuine real scam scams fraud fake trust trusted trustworthy'],
  ['caregiver', 'caregiver caregivers carer carers caring caretaker'],
  ['patient', 'patient patients sufferer'],
  ['account', 'account accounts profile profiles'],
  ['login', 'login log signin sign'],
].forEach(([c, words]) => words.split(' ').forEach((w) => { SYN[w] = 'syn_' + c; }));

export const norm = (s = '') => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[’'`]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9$]+/g, ' ').replace(/\s+/g, ' ').trim();

function stem(w) {
  if (w.length > 5 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 5 && w.endsWith('ing')) return w.slice(0, -3);
  if (w.length > 4 && w.endsWith('ed')) return w.slice(0, -2);
  if (w.length > 4 && w.endsWith('es') && !w.endsWith('ses')) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !w.endsWith('ss') && !w.endsWith('us')) return w.slice(0, -1);
  return w;
}

function tokens(s) {
  const out = new Set();
  for (const w of norm(s).split(' ')) {
    if (!w || STOP.has(w) || (w.length < 3 && !KEEP_SHORT.has(w))) continue;
    out.add(stem(w));
    if (SYN[w]) out.add(SYN[w]);
  }
  return out;
}

const trimTo = (text, n = 420) => {
  if (text.length <= n) return text;
  const cut = text.slice(0, n);
  const dot = cut.lastIndexOf('. ');
  return (dot > n * 0.5 ? cut.slice(0, dot + 1) : cut.replace(/\s+\S*$/, '') + '…');
};

/* ---------------- knowledge base ---------------- */
const LEGAL_LABEL = { '/privacy': 'Privacy Policy', '/terms': 'Terms of Use', '/gdpr': 'GDPR', '/cookies': 'Cookie Policy' };
const AUD_LABEL = { hcp: 'For healthcare professionals', caregiver: 'For caregivers', patient: 'For patients' };

function buildDocs() {
  const docs = [];
  const add = (d) => docs.push(d);
  INTENTS.forEach((it) => add({ ...it, kind: 'intent', boost: it.small ? 1 : 1.2 }));
  FAQ_GROUPS.forEach((g) => g.items.forEach((f) => add({ q: f.q, a: f.a, links: [[`/faq#fc-${g.id}`, `FAQ: ${g.title}`]], kind: 'faq', boost: 1.1 })));
  HOW_FAQ.forEach((f) => add({ q: f.q, a: f.a, links: [['/how-it-works', 'How it works']], kind: 'faq', boost: 1.05 }));
  Object.entries(AUDIENCE_FAQ).forEach(([key, list]) => list.forEach((f) => add({ q: f.q, a: f.a, links: [[AUDIENCE[key].path, AUD_LABEL[key]]], kind: 'faq', boost: 1.05 })));
  BLOG_FAQ.forEach((f) => add({ q: f.q, a: f.a, links: [[`/blog/${f.s}`, f.t]], kind: 'blog', boost: 0.92 }));
  Object.entries(LEGAL).forEach(([path, page]) => (page.sections || []).forEach((sec) => {
    const body = [...(sec.p || []), ...(sec.list || []).map((x) => `• ${x}`)].join(' ');
    add({ q: `${sec.title.replace(/^\d+\.\s*/, '')} — ${LEGAL_LABEL[path]}`, k: `${LEGAL_LABEL[path]}`, a: trimTo(body), links: [[`${path}#${sec.id}`, `${LEGAL_LABEL[path]}: ${sec.title.replace(/^\d+\.\s*/, '')}`]], kind: 'legal', boost: 0.85 });
  }));
  QUALITY_CHECKS.forEach((c) => add({ q: `What is ${c.name}?`, k: c.name, a: `${c.name}: ${c.note} It is one of the quality and security checks that protect every study.`, links: [['/trust-safety', 'Trust & Safety']], kind: 'quality', boost: 0.9 }));
  add({ q: 'How do you verify healthcare professionals?', k: VERIFICATION_PROTOCOLS.map((v) => v.name).join('|'), a: `Professional identity can be verified through: ${VERIFICATION_PROTOCOLS.map((v) => v.name.toLowerCase()).join(', ')}.`, links: [['/trust-safety', 'Trust & Safety']], kind: 'quality', boost: 0.95 });

  docs.forEach((d) => {
    d.qT = tokens(d.q);
    d.kT = new Set();
    d.kP = [];
    (d.k || '').split('|').filter(Boolean).forEach((p) => {
      tokens(p).forEach((t) => d.kT.add(t));
      const n = norm(p);
      if (n.includes(' ')) d.kP.push(n);
      else if (n) d.kP.push(n);
    });
    d.aT = tokens(d.a);
  });
  return docs;
}

let DOCS = null;
let IDF = null;
function index() {
  if (DOCS) return;
  DOCS = buildDocs();
  const df = new Map();
  DOCS.forEach((d) => new Set([...d.qT, ...d.kT, ...d.aT]).forEach((t) => df.set(t, (df.get(t) || 0) + 1)));
  IDF = (t) => Math.log(1 + DOCS.length / (df.get(t) || 0.5));
}

function rank(text) {
  index();
  const qn = ` ${norm(text)} `;
  const qT = tokens(text);
  const plain = [...qT].filter((t) => !t.startsWith('syn_'));
  const total = [...qT].reduce((n, t) => n + IDF(t), 0) || 1;
  const scored = DOCS.map((d) => {
    let s = 0;
    let covered = 0;
    qT.forEach((t) => {
      const w = IDF(t);
      const hit = (d.qT.has(t) ? 3 : 0) + (d.kT.has(t) ? 3 : 0) + (d.aT.has(t) ? 1 : 0);
      if (hit) s += w * Math.min(hit, 4);
      if (d.qT.has(t) || d.kT.has(t)) covered += w;
    });
    let phrase = 0;
    d.kP.forEach((p) => { if (qn.includes(` ${p} `)) phrase += p.includes(' ') ? 5 * p.split(' ').length : 4; });
    const cov = covered / total;
    let f = (s + phrase) * (0.4 + cov) * d.boost;
    if (d.small && plain.length > 3) f *= 0.25;
    return { d, f, cov, phrase };
  }).filter((x) => x.f > 0);
  scored.sort((a, b) => b.f - a.f);
  return { scored, plainCount: plain.length };
}

/* ---------------- entities ---------------- */
const ALIASES = { us: 'us', usa: 'us', 'united states of america': 'us', america: 'us', uk: 'gb', britain: 'gb', england: 'gb', 'great britain': 'gb', scotland: 'gb', wales: 'gb', uae: 'ae', emirates: 'ae', dubai: 'ae', ksa: 'sa', saudi: 'sa', korea: 'kr', 'south korea': 'kr', holland: 'nl', vietnam: 'vn', russia: 'ru', iran: 'ir', czechia: 'cz', 'czech republic': 'cz', turkiye: 'tr', bharat: 'in', hindustan: 'in' };
const COVER = new Map(COVERAGE.map((c) => [c.code, c]));
let COUNTRY_INDEX = null;
function countryIn(text) {
  if (!COUNTRY_INDEX) {
    COUNTRY_INDEX = [];
    ALL_COUNTRIES.forEach((c) => COUNTRY_INDEX.push([norm(c.name), c.code]));
    Object.entries(ALIASES).forEach(([a, code]) => COUNTRY_INDEX.push([a, code]));
    COUNTRY_INDEX.sort((a, b) => b[0].length - a[0].length);
  }
  const q = ` ${norm(text)} `;
  for (const [n, code] of COUNTRY_INDEX) {
    if (n.length < 3 && !['us', 'uk'].includes(n)) continue;
    if (n === 'us' && !/\b(in|from|the) us\b/.test(q)) continue; // "us" is usually a pronoun
    if (q.includes(` ${n} `)) return code;
  }
  return null;
}

function countryAnswer(code) {
  const c = ALL_COUNTRIES.find((x) => x.code === code);
  const name = c ? c.name : code.toUpperCase();
  const cov = COVER.get(code);
  if (cov) {
    const region = REGIONS.find((r) => r.id === cov.region)?.name;
    const pay = code === 'in' ? 'UPI, PayPal, bank or wire transfer, gift cards and vouchers' : 'PayPal, bank or wire transfer, gift cards and vouchers (UPI is India-only)';
    return { a: `Yes — ${name} is one of our ${COVERAGE.length} countries (${region}). Members there can join free as a healthcare professional, caregiver or patient, and redeem rewards by ${pay}. Options can vary by study.`, links: [['/earn#countries', 'All 55 countries'], ['/join', 'Join free']] };
  }
  return { a: `${name} is not one of our ${COVERAGE.length} recruitment countries right now, so we can’t open an account there yet. Leave your details and the team will let you know if that changes.`, links: [['/earn#countries', 'See the 55 countries']], lead: true };
}

let CONDS = null;
function conditionIn(text) {
  if (!CONDS) {
    CONDS = [];
    THERAPY_AREAS.forEach((a) => a.items.forEach((item) => {
      const names = new Set([item]);
      item.split(/[()]/).forEach((p) => p.split(/,| & | and |\//).forEach((x) => x.trim().length > 3 && names.add(x.trim())));
      [...names].forEach((n) => { const last = norm(n).split(' ').pop(); if (/(itis|osis|aemia|emia|diabetes|dementia|obesity|apnoea|apnea|asthma|migraine|epilepsy|glaucoma|psoriasis|eczema|autism|adhd)$/.test(last)) names.add(last); });
      names.forEach((n) => { const k = norm(n); if (k.length > 3 && !['cancer', 'disease', 'recovery', 'problems', 'health', 'care'].includes(k)) CONDS.push([k, n === item || n.length > 6 && item.toLowerCase().startsWith(n.toLowerCase()) ? item : n.charAt(0).toUpperCase() + n.slice(1), a.area]); });
    }));
    CONDS.sort((a, b) => b[0].length - a[0].length);
  }
  const q = ` ${norm(text)} `;
  for (const c of CONDS) if (q.includes(` ${c[0]} `) || q.includes(` ${c[0]}s `)) return c;
  return null;
}

let JOBS = null;
function jobIn(text) {
  if (!JOBS) {
    JOBS = allJobs().map((j) => ({ ...j, n: norm(j.t.replace(/\([^)]*\)/g, ' ')) })).filter((j) => j.n.length > 3);
  }
  const q = norm(text);
  const m = q.match(/\b(?:i am|im|i work as|working as|work as|my job is|my profession is|my role is|as) (?:an? )?([a-z ]{4,40})/);
  const phrase = m ? m[1].replace(/\b(in|at|with|and|from|for|who|can|do|i|looking|interested|want|working)\b.*$/, '').trim() : '';
  // 1) a full job title written in the question; 2) the role after "I am a / I work as …"
  const full = JOBS.filter((j) => j.n.length > 6 && ` ${q} `.includes(` ${j.n} `)).sort((a, b) => b.n.length - a.n.length)[0];
  if (full) return full;
  if (phrase.length >= 4) {
    const hits = JOBS.filter((j) => ` ${j.n} `.includes(` ${phrase} `));
    if (hits.length) return { ...hits.sort((a, b) => a.n.length - b.n.length)[0], count: hits.length, phrase };
  }
  return null;
}

/* ---------------- public API ---------------- */
const rel = (scored, best) => {
  const seen = new Set([best.d.q]);
  const out = [];
  for (const x of scored.slice(1, 12)) {
    if (x.f < best.f * 0.42 || seen.has(x.d.q) || x.d.small) continue;
    seen.add(x.d.q);
    out.push(x.d.q);
    if (out.length === 3) break;
  }
  return out;
};

/**
 * @returns {{ a: string, links?: [string,string][], human?: boolean, lead?: boolean, related?: string[], id?: string }
 *          | { unknown: true }}
 */
export function respond(text) {
  // Under-18 check first: "I am 16", "aged 17", "15 years old"
  const nq = norm(text);
  if (/\b(?:i am|im|aged?|age is)\s*(1[0-7]|[1-9])\b/.test(nq) || /\b(1[0-7]|[1-9]) ?(?:years?|yrs?|yo)\b/.test(nq)) {
    const age = INTENTS.find((i) => i.id === 'age');
    return { id: 'age', a: age.a, links: age.links, related: ['Who can join?'] };
  }
  const { scored, plainCount } = rank(text);
  const best = scored[0];
  const strong = best && best.cov >= 0.55 && best.f >= 9;

  // A country named in the question wins unless the question is about a payout method.
  const cc0 = countryIn(text);
  if (cc0 && !(best && strong && ['upi', 'paypal', 'bank', 'gift', 'methods', 'paytime', 'threshold', 'notpaid', 'vpn'].includes(best.d.id))) {
    return { ...countryAnswer(cc0), id: 'country' };
  }
  // Other entities win when the general match is weak or generic.
  const generic = !best || !strong || ['countries', 'who', 'patient', 'conditions', 'hcp', 'roles', 'join', 'whichprofile'].includes(best.d.id);
  if (generic) {
    const cc = countryIn(text);
    if (cc) return { ...countryAnswer(cc), id: 'country' };
    const cond = conditionIn(text);
    if (cond) {
      return { id: 'condition', a: `Yes — ${cond[1]} is one of the ${CONDITION_COUNT}+ conditions we research (${cond[2]}). If you live with it, join as a patient; if you look after someone who does, join as a caregiver. Sharing your conditions is optional and confidential, and patients typically earn $${RATE_BANDS[0].min}–$${RATE_BANDS[0].max} per survey.`, links: [['/patients', 'For patients'], ['/caregivers', 'For caregivers'], ['/join', 'Join free']] };
    }
    const job = jobIn(text);
    if (job) {
      const hcp = RATE_BANDS.find((b) => b.id === 'hcp');
      return { id: 'job', a: `Yes — “${job.t}” is one of the 1,300+ healthcare job titles we recruit (${job.roleLabel}${job.group ? ` · ${job.group}` : ''}). Join as a Healthcare Professional; you’ll pick it during sign-up. Professional surveys typically pay $${hcp.min}–$${hcp.max}.`, links: [['/healthcare-professionals', 'Search all job titles'], ['/join#hcp', 'Join as a professional']] };
    }
  }

  if (!best) return { unknown: true };
  const weakKind = best.d.kind === 'blog' || best.d.kind === 'legal';
  const enough = (best.cov >= (weakKind ? 0.5 : 0.34) && best.f >= 6) || best.phrase >= 8 || (plainCount <= 1 && best.d.kind === 'intent' && best.f >= 4);
  if (!enough) return { unknown: true, related: scored.slice(0, 3).filter((x) => x.f >= 4 && !x.d.small).map((x) => x.d.q) };
  const d = best.d;
  return { id: d.id || d.kind, a: d.a, links: d.links, human: d.human, lead: d.lead, small: d.small, related: d.small ? [] : rel(scored, best) };
}

export const KB_SIZE = () => { index(); return DOCS.length; };
